module TopModule (
    input  [3:0] x,
    output       f
);
    assign f = (~x[2] & ~x[1]) |
               (x[3] & ~x[0]) |
               (x[3] & x[2] & x[1]);
endmodule

module TopModule (
    input  clk,
    input  a,
    input  b,
    output q,
    output state
);

    reg ff;

    always @(posedge clk) begin
        ff <= a ^ b ^ ff;
    end

    assign state = ff;
    assign q = a ^ b ^ ff;

endmodule

module TopModule(
    input  logic clk,
    input  logic reset,
    input  logic [2:0] s,
    output logic fr2,
    output logic fr1,
    output logic fr0,
    output logic dfr
);

    logic [1:0] level;
    logic       dfr_reg;

    logic [1:0] next_level;
    logic       next_dfr;

    always_comb begin
        if (s[2])
            next_level = 2'd3;
        else if (s[1])
            next_level = 2'd2;
        else if (s[0])
            next_level = 2'd1;
        else
            next_level = 2'd0;

        if (next_level == 2'd0)
            next_dfr = 1'b1;
        else if (next_level == 2'd3)
            next_dfr = 1'b0;
        else if (next_level == level)
            next_dfr = dfr_reg;
        else if (next_level > level)
            next_dfr = 1'b1;
        else
            next_dfr = 1'b0;
    end

    always_ff @(posedge clk) begin
        if (reset) begin
            level   <= 2'd0;
            dfr_reg <= 1'b1;
        end else begin
            level   <= next_level;
            dfr_reg <= next_dfr;
        end
    end

    always_comb begin
        case (level)
            2'd0: begin
                fr2 = 1'b1;
                fr1 = 1'b1;
                fr0 = 1'b1;
            end
            2'd1: begin
                fr2 = 1'b0;
                fr1 = 1'b1;
                fr0 = 1'b1;
            end
            2'd2: begin
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b1;
            end
            default: begin
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b0;
            end
        endcase
        dfr = dfr_reg;
    end

endmodule

module TopModule (
    input  logic        clk,
    input  logic        reset,
    input  logic [7:0]  in,
    output logic [23:0] out_bytes,
    output logic        done
);

    typedef enum logic [1:0] {
        IDLE  = 2'd0,
        BYTE1 = 2'd1,
        BYTE2 = 2'd2,
        BYTE3 = 2'd3
    } state_t;

    state_t state;
    logic [7:0] b1, b2, b3;

    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            done      <= 1'b0;
            out_bytes <= 24'h000000;
            b1        <= 8'h00;
            b2        <= 8'h00;
            b3        <= 8'h00;
        end else begin
            done <= (state == BYTE3);

            case (state)
                IDLE: begin
                    if (in[3]) begin
                        state <= BYTE1;
                        b1    <= in;
                    end
                end

                BYTE1: begin
                    state <= BYTE2;
                    b2    <= in;
                end

                BYTE2: begin
                    state <= BYTE3;
                    b3    <= in;
                end

                BYTE3: begin
                    out_bytes <= {b1, b2, b3};
                    if (in[3]) begin
                        state <= BYTE1;
                        b1    <= in;
                    end else begin
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

